/*
 * A131903  Integers x such that d(k)=d(x) for some 0<k<x, where d=A000005 is
 *          the number of divisors.
 * https://oeis.org/A131903
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) is the n-th integer x such that there exists k<x with
 *            d(k)=d(x), where d(m) = number of divisors of m. The sequence is
 *            generated by scanning integers in order and recording those
 *            whose divisor count has already been seen for a smaller integer
 * Range:     u8 n <= 67, u16 n <= 67, u32 n <= 67, u64 n <= 67, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

static seq_t *results   = NULL;   /* array of sequence values */
static size_t  res_len   = 0;      /* number of values stored */
static size_t  res_cap   = 0;      /* allocated capacity of results */

static uint64_t *min_d  = NULL;   /* minimal integer seen for each divisor count */
static size_t   min_cap = 0;       /* allocated capacity for min_d */

static uint64_t processed = 0;    /* numbers processed so far */

/* Ensure the results array can hold at least 'need' elements. */
static void ensure_results_cap(size_t need)
{
    if (need <= res_cap) return;
    size_t new_cap = res_cap ? res_cap * 2 : 8;
    while (new_cap < need) new_cap <<= 1;
    seq_t *tmp = (seq_t*)realloc(results, new_cap * sizeof(seq_t));
    if (!tmp) exit(EXIT_FAILURE);
    results = tmp;
    res_cap = new_cap;
}

/* Ensure the min_d array can hold indices up to 'need'. */
static void ensure_min_cap(size_t need)
{
    if (need <= min_cap) return;
    size_t new_cap = min_cap ? min_cap * 2 : 16;
    while (new_cap <= need) new_cap <<= 1;
    uint64_t *tmp = (uint64_t*)realloc(min_d, new_cap * sizeof(uint64_t));
    if (!tmp) exit(EXIT_FAILURE);
    /* Initialize newly allocated area to 0. */
    for (size_t i = min_cap; i < new_cap; ++i) tmp[i] = 0;
    min_d   = tmp;
    min_cap = new_cap;
}

/* Compute the divisor count of n (n>=1) by trial division. */
static uint64_t divisor_count(uint64_t n)
{
    if (n == 1) return 1;
    uint64_t cnt = 1;
    uint64_t tmp = n;
    for (uint64_t p = 2; p * p <= tmp; ++p) {
        if (tmp % p == 0) {
            uint64_t exp = 0;
            while (tmp % p == 0) { tmp /= p; ++exp; }
            cnt *= (exp + 1);
        }
    }
    if (tmp > 1) cnt *= 2;
    return cnt;
}

/* Expand the precomputation until we have at least 'need' terms. */
static void compute_up_to(idx_t need)
{
    size_t target = (size_t)need;
    while (res_len < target) {
        size_t new_limit = processed ? processed * 2 : 1024;
        if (new_limit <= processed) new_limit = processed + 1024;
        /* Process integers from processed+1 up to new_limit inclusive. */
        for (uint64_t x = processed + 1; x <= new_limit; ++x) {
            uint64_t d = divisor_count(x);
            ensure_min_cap((size_t)d);
            if (min_d[d] == 0) {
                /* first occurrence of this divisor count */
                min_d[d] = x;
            } else if (x > min_d[d]) {
                /* not the first, so it belongs to the sequence */
                ensure_results_cap(res_len + 1);
                results[res_len++] = (seq_t)x;
            }
        }
        processed = new_limit;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined, but keep safe */
    compute_up_to(n);
    return results[(size_t)n - 1];
}
